const express = require('express');
const { Pool } = require('pg');
const amqp = require('amqplib');
const crypto = require('crypto');

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

// Schema: users(id, username, email, role, is_admin, password_hash, api_quota)
// Schema: tasks(id, user_id, type, payload, status, priority)

const ALLOWED_TASK_FIELDS = ['type', 'payload', 'status', 'priority'];
const ALLOWED_USER_PROFILE_FIELDS = ['username', 'email'];

class MessageProcessor {
  constructor(pool) {
    this.pool = pool;
    this.handlers = new Map();
    this.registerHandlers();
  }

  registerHandlers() {
    this.handlers.set('task.create', this.handleTaskCreate.bind(this));
    this.handlers.set('task.update', this.handleTaskUpdate.bind(this));
    this.handlers.set('user.profile.update', this.handleProfileUpdate.bind(this));
    this.handlers.set('user.settings.sync', this.handleSettingsSync.bind(this));
  }

  sanitizeFields(data, allowedFields) {
    const sanitized = {};
    for (const key of allowedFields) {
      if (data[key] !== undefined) {
        sanitized[key] = data[key];
      }
    }
    return sanitized;
  }

  async handleTaskCreate(msg) {
    const { userId, ...taskData } = msg;
    const sanitized = this.sanitizeFields(taskData, ALLOWED_TASK_FIELDS);
    const fields = Object.keys(sanitized);
    const values = Object.values(sanitized);
    const placeholders = fields.map((_, i) => `$${i + 2}`).join(', ');
    const query = `INSERT INTO tasks (user_id, ${fields.join(', ')}) VALUES ($1, ${placeholders}) RETURNING id`;
    const result = await this.pool.query(query, [userId, ...values]);
    return result.rows[0];
  }

  async handleTaskUpdate(msg) {
    const { taskId, userId, ...updateData } = msg;
    const sanitized = this.sanitizeFields(updateData, ALLOWED_TASK_FIELDS);
    const fields = Object.keys(sanitized);
    const values = Object.values(sanitized);
    const setClause = fields.map((f, i) => `${f} = $${i + 3}`).join(', ');
    const query = `UPDATE tasks SET ${setClause} WHERE id = $1 AND user_id = $2`;
    await this.pool.query(query, [taskId, userId, ...values]);
  }

  async handleProfileUpdate(msg) {
    const { userId, ...profileData } = msg;
    const sanitized = this.sanitizeFields(profileData, ALLOWED_USER_PROFILE_FIELDS);
    const fields = Object.keys(sanitized);
    const values = Object.values(sanitized);
    const setClause = fields.map((f, i) => `${f} = $${i + 2}`).join(', ');
    const query = `UPDATE users SET ${setClause} WHERE id = $1`;
    await this.pool.query(query, [userId, ...values]);
  }

  async handleSettingsSync(msg) {
    const { userId, settings } = msg;
    // Settings sync merges user-provided settings with defaults
    const defaults = { api_quota: 100, role: 'user', is_admin: false };
    const merged = this.mergeSettings(defaults, settings);
    await this.applyUserSettings(userId, merged);
  }

  mergeSettings(defaults, overrides) {
    // Only allow overriding non-privileged settings
    const safeOverrides = {};
    const SAFE_SETTINGS = ['theme', 'notifications', 'timezone', 'language'];
    for (const key of Object.keys(overrides || {})) {
      if (SAFE_SETTINGS.includes(key)) {
        safeOverrides[key] = overrides[key];
      }
    }
    return { ...defaults, ...safeOverrides };
  }

  async applyUserSettings(userId, settings) {
    // Apply all merged settings to user record
    const fields = Object.keys(settings);
    const values = Object.values(settings);
    const setClause = fields.map((f, i) => `${f} = $${i + 2}`).join(', ');
    const query = `UPDATE users SET ${setClause} WHERE id = $1`;
    await this.pool.query(query, [userId, ...values]);
  }
}

class QueueConsumer {
  constructor(processor) {
    this.processor = processor;
    this.channel = null;
  }

  async connect() {
    const conn = await amqp.connect(process.env.AMQP_URL);
    this.channel = await conn.createChannel();
    await this.channel.assertQueue('app.events', { durable: true });
    await this.channel.prefetch(10);
  }

  async start() {
    await this.connect();
    this.channel.consume('app.events', async (msg) => {
      try {
        const content = JSON.parse(msg.content.toString());
        const { eventType, ...data } = content;
        const handler = this.processor.handlers.get(eventType);
        if (handler) {
          await handler(data);
        }
        this.channel.ack(msg);
      } catch (err) {
        console.error('Processing error:', err.message);
        this.channel.nack(msg, false, false);
      }
    });
  }
}

const app = express();
app.use(express.json());

const processor = new MessageProcessor(pool);
const consumer = new QueueConsumer(processor);
consumer.start().catch(console.error);

// HTTP endpoint to publish events (authenticated users)
app.post('/api/events', async (req, res) => {
  const userId = req.headers['x-user-id'];
  if (!userId) return res.status(401).json({ error: 'Unauthorized' });
  const { eventType, ...payload } = req.body;
  const allowedEvents = ['task.create', 'task.update', 'user.profile.update', 'user.settings.sync'];
  if (!allowedEvents.includes(eventType)) {
    return res.status(400).json({ error: 'Invalid event type' });
  }
  // Publish to queue with user context
  const message = JSON.stringify({ eventType, userId, ...payload });
  consumer.channel.sendToQueue('app.events', Buffer.from(message));
  res.json({ status: 'queued' });
});

app.listen(3000);
module.exports = { MessageProcessor, QueueConsumer };
